## Code Example
```javascript
// Minimal enrichment example: validate fields and update per-device counter
const AWS = require('aws-sdk');
const ddb = new AWS.DynamoDB.DocumentClient();
exports.handler = async (event) => {
  const record = JSON.parse(Buffer.from(event.data, 'base64').toString());
  if (!record.deviceId || !record.ts) throw new Error('Missing required fields');
  const key = { deviceId: record.deviceId };
  const upd = await ddb.update({
    TableName: 'DeviceCounters',
    Key: key,
    UpdateExpression: 'SET lastTs = :t, count = if_not_exists(count, :zero) + 1',
    ExpressionAttributeValues: { ':t': record.ts, ':zero': 0 },
    ReturnValues: 'UPDATED_NEW'
  }).promise();
  // forward or fail logic would follow
  return { status: 'ok', counters: upd.Attributes };
};
```

